INSERT INTO public.erp_ajuda_campo (chave, rota, grupo, vertical, ordem, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum)
VALUES
('projetos.painel.acao.configurar_bdi','/dashboard/projetos','Ações','hub_projetos',1,'Configurar BDI da empresa','Abre as configurações do Hub para informar o BDI e as margens de referência.','O BDI entra no preço de todo serviço do catálogo e de toda proposta.','BDI 25% com lucro de 8%','Orçar antes de configurar o BDI e sair com preço abaixo do custo.'),
('projetos.painel.acao.abrir_funil','/dashboard/projetos','Ações','hub_projetos',2,'Abrir o funil de oportunidades','Abre o quadro de oportunidades para cadastrar ou mover negociações.','É o começo do caminho: oportunidade vira proposta, proposta aprovada vira obra.','Cliente pediu orçamento de reforma','Criar a obra direto e perder o histórico da negociação.'),
('projetos.painel.kpi.obras_ativas','/dashboard/projetos','Indicadores','hub_projetos',3,'Obras em andamento','Indicador calculado, não se preenche. Conta as obras com situação "em andamento".','Mostra quantas obras a empresa está tocando agora.','3','Esperar ver aqui obra pausada ou concluída: elas aparecem em "Obras por situação".'),
('projetos.painel.kpi.valor_obras','/dashboard/projetos','Indicadores','hub_projetos',4,'Valor das obras em andamento','Indicador calculado. Soma o valor previsto de cada obra em andamento.','Dá o tamanho da carteira em execução.','R$ 268.000,00','Confundir com o que já foi faturado: aqui é o previsto.'),
('projetos.painel.kpi.margem_prevista','/dashboard/projetos','Indicadores','hub_projetos',5,'Margem prevista das obras','Indicador calculado: (receita prevista − custo previsto) ÷ receita prevista dos itens das obras em andamento.','Mostra se a carteira em execução foi vendida com margem saudável. "—" quando nenhuma obra tem itens com valor.','25,9%','Ler como margem realizada: a realizada está em Resultado por obra.'),
('projetos.painel.kpi.propostas_pendentes','/dashboard/projetos','Indicadores','hub_projetos',6,'Propostas pendentes','Indicador calculado. Conta os orçamentos em rascunho ou enviados ao cliente.','Mostra o que ainda depende de resposta do cliente ou de terminar o orçamento.','2','Esquecer proposta enviada sem retorno: ela fica contando aqui.'),
('projetos.painel.kpi.pagar_aberto','/dashboard/projetos','Indicadores','hub_projetos',7,'Contas a pagar abertas','Indicador calculado. Soma os títulos a pagar abertos ou vencidos da empresa.','Ajuda a ver o compromisso de caixa enquanto as obras andam.','R$ 12.500,00','Achar que é só da obra: é o total da empresa.'),
('projetos.painel.kpi.receber_aberto','/dashboard/projetos','Indicadores','hub_projetos',8,'Contas a receber abertas','Indicador calculado. Soma os títulos a receber abertos ou vencidos da empresa.','Mostra quanto ainda vai entrar das medições e vendas.','R$ 40.000,00','Achar que é só da obra: é o total da empresa.'),
('projetos.painel.funil','/dashboard/projetos','Funil','hub_projetos',9,'Funil de oportunidades','Indicador calculado das oportunidades da empresa. Clique para abrir o funil.','Em aberto = todas fora de Ganho e Perdido; o valor usa o da proposta ou, sem proposta, o estimado.','3 em aberto, R$ 194.000,00','Deixar oportunidade perdida sem marcar e inflar o valor em aberto.'),
('projetos.painel.obras_situacao','/dashboard/projetos','Obras','hub_projetos',10,'Obras por situação','Indicador calculado. Conta as obras da empresa em cada situação. Clique para abrir a lista de obras.','Mostra de relance o que está andando, parado, entregue ou cancelado.','3 em andamento, 1 concluída','Não pausar a obra parada e ela seguir contando como em andamento.')
